import { pollConfig } from "@/config/poll.config";
import { normalizeText } from "@/lib/normalize";
import { SEED_RESPONDENTS, seedSlots } from "./respondents";

const lit = (s: string) => `'${s.replace(/'/g, "''")}'`;

/**
 * Idempotent seed SQL (static, trusted data only). Seeded rows get an
 * edit_token_hash of 'seed', which can never equal a real sha256 hash, so no
 * one can "edit" them through the form – but name + organization overwrite
 * still works, which is handy for testing that flow.
 */
export function buildSeedSql(): string {
  const out: string[] = [
    "-- Generated by `npm run seed:sql` – fictional test respondents.",
    "begin;",
    `insert into poll (title, slot_config) values (${lit(pollConfig.title)}, ${lit(
      JSON.stringify(pollConfig.grid),
    )}::jsonb) on conflict (singleton) do nothing;`,
  ];
  SEED_RESPONDENTS.forEach((r, idx) => {
    // U+001F built with chr(31) so the file has no raw control characters.
    const key = `${lit(normalizeText(r.name))} || chr(31) || ${lit(normalizeText(r.organization))}`;
    const created = `now() - interval '${(SEED_RESPONDENTS.length - idx) * 3} hours'`;
    out.push(
      `insert into response (poll_id, name, name_key, organization, country, timezone, edit_token_hash, created_at, updated_at)
select id, ${lit(r.name)}, ${key}, ${lit(r.organization)}, ${lit(r.country)}, ${lit(r.timezone)}, 'seed', ${created}, ${created}
  from poll on conflict (poll_id, name_key) do nothing;`,
    );
    const slots = seedSlots(r);
    if (slots.length) {
      const values = slots
        .map((s) => `(${s.weekday}, ${s.startHour}, '${s.preference}')`)
        .join(", ");
      out.push(
        `insert into response_slot (response_id, weekday, start_hour, preference)
select r.id, v.weekday, v.start_hour, v.preference::slot_preference
  from response r cross join (values ${values}) as v(weekday, start_hour, preference)
 where r.name_key = ${key}
on conflict do nothing;`,
      );
    }
  });
  out.push("commit;", "");
  return out.join("\n");
}
